import { SINGING_RECORDING } from './personal-recording-data.js';

// Declarative media only. Importing this catalogue does not fetch a recording,
// create a player or start playback. The room assigns a source after Open.
function item(value) {
  return Object.freeze({ ...value, sourceIds: Object.freeze(value.sourceIds) });
}

